corrected_code:
const serverless = require('@codegenie/serverless-express');
const express = require('express');
const LegalDocument = require('../models/LegalDocument');

const app = express();

app.get('/api/legal/agreements/:docId', async (req, res) => {
  const authorizer = req.apiGateway.event.requestContext.authorizer;
  if (authorizer.role !== 'LEGAL_AUDITOR') {
    return res.status(403).json({ error: 'Requires LEGAL_AUDITOR role' });
  }

  const doc = await LegalDocument.findOne({
    _id: req.params.docId,
    organizationId: authorizer.orgId
  });
  if (!doc) {
    return res.status(403).json({ error: 'Document not found or access denied for your organization' });
  }

  res.json({ document: doc });
});

exports.handler = serverless({ app });
